import { readdir, readFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { resolve } from 'node:path';

const require = createRequire(import.meta.url);
const { parse } = require('libpg-query');
const migrationDirectory = resolve(process.cwd(), 'supabase', 'migrations');
// Preserve the 12-digit timestamps generated by the legacy project while all
// newly generated migrations use the current 14-digit CLI format.
const migrationName = /^\d{12}(?:\d{2})?_[a-z0-9_]+\.sql$/u;

const files = (await readdir(migrationDirectory))
  .filter((file) => file.endsWith('.sql'))
  .sort((left, right) => left.localeCompare(right));

const timestamps = new Set();
let latestTimestamp = '';
let releaseMarkerTimestamp = '';
for (const file of files) {
  if (!migrationName.test(file)) throw new Error(`invalid_migration_name:${file}`);
  const timestamp = file.slice(0, file.indexOf('_'));
  if (timestamps.has(timestamp)) throw new Error(`duplicate_migration_timestamp:${timestamp}`);
  timestamps.add(timestamp);
  latestTimestamp = timestamp;
  if (/_release_marker\.sql$/u.test(file)) {
    releaseMarkerTimestamp = timestamp;
  }

  const sql = await readFile(resolve(migrationDirectory, file), 'utf8');
  if (!sql.trim()) throw new Error(`empty_migration:${file}`);
  try {
    await parse(sql);
  } catch (error) {
    const reason = error instanceof Error ? error.message.split('\n')[0] : 'parse_failed';
    throw new Error(`invalid_postgres_sql:${file}:${reason}`);
  }
}

if (!releaseMarkerTimestamp) throw new Error('missing_marketplace_release_marker');
if (releaseMarkerTimestamp !== latestTimestamp) {
  throw new Error(`release_marker_must_be_latest:${releaseMarkerTimestamp}:${latestTimestamp}`);
}

const readinessRoute = await readFile(
  resolve(process.cwd(), 'app', 'api', 'health', 'ready', 'route.ts'),
  'utf8',
);
if (!readinessRoute.includes(`EXPECTED_SCHEMA_VERSION = '${releaseMarkerTimestamp}'`)) {
  throw new Error(`readiness_schema_version_drift:${releaseMarkerTimestamp}`);
}

process.stdout.write(`Validated ${files.length} PostgreSQL migrations.\n`);
